import type { IamActionCatalog } from "@fluxiq/contracts/iam";

/** TS source for the one-entry-per-line `packages/contracts/src/iam/actions.generated.ts`. */
export function renderIamActionCatalogModule(catalog: IamActionCatalog): string {
  return [
    "// GENERATED by renderIamActionCatalogModule (packages/fluxiq/src/platform/iam/catalog). Do not edit.",
    'import type { IamActionCatalog } from "./action/index.ts";',
    "",
    "export const IAM_ACTION_CATALOG: IamActionCatalog = [",
    ...catalog.map((entry, index) => `  ${JSON.stringify(entry)}${index < catalog.length - 1 ? "," : ""}`),
    "];",
    ""
  ].join("\n");
}
